import numpy as np
from scipy.optimize import linprog

def get_T_sets_v2(n):
    m = n*n
    f = np.zeros((n, n), dtype=int)
    for x in range(n):
        for y in range(n):
            f[x, y] = x*n + y + 1
    h = np.zeros((n, n), dtype=int)
    for y in range(n):
        for z in range(n):
            h[y, z] = y*n + z + 1
    g = np.zeros((n, n), dtype=int)
    for x in range(n):
        for z in range(n):
            g[x, z] = x*n + z + 1

    T_sets = set()
    for x in range(n):
        for y in range(n):
            for z in range(n):
                T_sets.add(frozenset([f[x, y], h[y, z], g[x, z]]))
    return list(T_sets), m

def solve_for_n_v2(n):
    T_sets, m = get_T_sets_v2(n)
    num_T = len(T_sets)
    A = np.zeros((m, num_T))
    for j, T in enumerate(T_sets):
        for i in T:
            A[i-1, j] = 1

    c = -np.ones(num_T)
    res = linprog(c, A_ub=A, b_ub=np.full(m, n), bounds=(0, None), method='highs')
    return -res.fun if res.success else None

for n in range(1, 5):
    print(f"n={n}, k={solve_for_n_v2(n)}")

